# Functions use explicit result variables to avoid subshells in the evaluator.
json_quote() {
    local text=$1 char code i
    text=${text//\\/\\\\}
    text=${text//\"/\\\"}
    for ((i=1; i<32; i++)); do
        printf -v char '\\%03o' "$i"
        printf -v char '%b' "$char"
        printf -v code '\\u%04x' "$i"
        text=${text//"$char"/"$code"}
    done
    JSON="\"$text\""
}

split_segments() {
    local rest=$1
    SEGMENTS=()
    while [[ $rest =~ (~|\^|[0-9]+|[a-zA-Z]+) ]]; do
        SEGMENTS+=("${BASH_REMATCH[1]}")
        rest=${rest#*"${BASH_REMATCH[1]}"}
    done
}

vercmp() {
    local a=$1 b=$2 p q i n
    local -a x y
    CMP=0
    [[ $a == "$b" ]] && return
    split_segments "$a"; x=("${SEGMENTS[@]}")
    split_segments "$b"; y=("${SEGMENTS[@]}")
    n=${#x[@]}
    ((${#y[@]} > n)) && n=${#y[@]}
    for ((i=0; i<n; i++)); do
        p=${x[i]} q=${y[i]}
        [[ $p == "$q" ]] && continue
        if [[ $p == '~' ]]; then CMP=-1; return; fi
        if [[ $q == '~' ]]; then CMP=1; return; fi
        if [[ -z $p ]]; then CMP=-1; return; fi
        if [[ -z $q ]]; then CMP=1; return; fi
        if [[ $p =~ ^[0-9]+$ && $q =~ ^[0-9]+$ ]]; then
            # awk uses the same double precision numeric comparison as JS.
            CMP=$(awk -v p="$p" -v q="$q" 'BEGIN {print (p+0>q+0)?1:((p+0<q+0)?-1:0)}')
            ((CMP != 0)) && return
        elif [[ $p =~ ^[0-9]+$ ]]; then CMP=1; return
        elif [[ $q =~ ^[0-9]+$ ]]; then CMP=-1; return
        elif [[ $p < $q ]]; then CMP=-1; return
        else CMP=1; return
        fi
    done
    return 0
}

upstream_of() {
    U_FULL='' U_BRANCH=
    if [[ $1 =~ ^([0-9]+)\.([0-9]+)\.([0-9]+) ]]; then
        U_FULL=${BASH_REMATCH[1]}.${BASH_REMATCH[2]}.${BASH_REMATCH[3]}
        U_BRANCH=${BASH_REMATCH[1]}.${BASH_REMATCH[2]}
    fi
}

upstream_status() {
    upstream_of "$1"
    STATUS=unknown ANCIENT=0 UP_FIXED=
    [[ -z $U_FULL ]] && return
    vercmp "$U_FULL" "$MIN_AFFECTED"
    if ((CMP < 0)); then ANCIENT=1; return; fi
    UP_FIXED=${FIXED_UPSTREAM[$U_BRANCH]}
    if [[ -z $UP_FIXED ]]; then STATUS=eol; return; fi
    vercmp "$U_FULL" "$UP_FIXED"
    STATUS=vulnerable
    ((CMP >= 0)) && STATUS=fixed
    return 0
}

parse_line() {
    local line=$1 t regex noarch dver
    P_TYPE='' P_NAME='' P_VERSION='' P_RELEASE='' P_FULL='' P_RAW=
    # JS trims both ends of raw; dpkg descriptions remain part of raw.
    t=${line#"${line%%[![:space:]]*}"}
    t=${t%"${t##*[![:space:]]}"}
    [[ -z $t ]] && return 1
    P_RAW=$t
    regex='^[Pp][Hh][Pp] ([0-9]+\.[0-9]+\.[0-9]+)[^[:space:]]*[[:space:]]+\(([Cc][Ll][Ii]|[Cc][Gg][Ii]-[Ff][Cc][Gg][Ii]|[Ff][Pp][Mm]-[Ff][Cc][Gg][Ii]|[Aa][Pp][Aa][Cc][Hh][Ee]2[Hh][Aa][Nn][Dd][Ll][Ee][Rr]|[Ll][Ii][Tt][Ee][Ss][Pp][Ee][Ee][Dd]|[Ff][Rr][Aa][Nn][Kk][Ee][Nn][Pp][Hh][Pp])'
    if [[ $t =~ $regex ]]; then
        P_TYPE=phpv P_NAME=php P_VERSION=${BASH_REMATCH[1]}
        return 0
    fi
    regex='^[a-z][a-z][[:space:]]+([^[:space:]]+)[[:space:]]+([^[:space:]]+)[[:space:]]+[^[:space:]]+'
    if [[ $t =~ $regex ]]; then
        P_NAME=${BASH_REMATCH[1]%%:*} dver=${BASH_REMATCH[2]}
        if [[ $P_NAME == php* ]]; then
            [[ $dver =~ ^[0-9]+: ]] && dver=${dver#*:}
            P_TYPE=deb P_VERSION=$dver P_FULL=$dver
            return 0
        fi
    fi
    regex='^(php[a-zA-Z0-9_.+-]*)(/[^[:space:]]+)?[[:space:]]+([0-9][^[:space:]]*)'
    if [[ $t =~ $regex ]]; then
        P_NAME=${BASH_REMATCH[1]} dver=${BASH_REMATCH[3]}
        regex='[~+]|ubuntu|deb[0-9]|\<sury\>'
        if [[ $dver =~ $regex ]]; then
            [[ $dver =~ ^[0-9]+: ]] && dver=${dver#*:}
            P_TYPE=deb P_VERSION=$dver P_FULL=$dver
            return 0
        fi
    fi
    regex='^(php[0-9]*(-[a-z0-9_]+)*)-([0-9]+\.[0-9]+\.[0-9]+[^-[:space:]]*)-(r[0-9]+)$'
    if [[ $t =~ $regex ]]; then
        P_TYPE=apk P_NAME=${BASH_REMATCH[1]} P_VERSION=${BASH_REMATCH[3]} P_RELEASE=${BASH_REMATCH[4]}
        P_FULL=$P_VERSION-$P_RELEASE
        return 0
    fi
    noarch=${t%%[[:space:]]*}
    regex='\.(x86_64|aarch64|noarch|i686|i386|ppc64le|s390x|src)$'
    [[ $noarch =~ $regex ]] && noarch=${noarch%"${BASH_REMATCH[0]}"}
    # JS's lazy name match selects the first suffix satisfying version-release.
    local suffix=$noarch prefix='' part
    while [[ $suffix == *-* ]]; do
        part=${suffix%%-*}
        prefix=${prefix:+$prefix-}$part
        suffix=${suffix#*-}
        regex='^([0-9]+:)?([0-9][^-]*)-([^-]+)$'
        if [[ $suffix =~ $regex ]]; then
            P_NAME=$prefix P_VERSION=${BASH_REMATCH[2]} P_RELEASE=${BASH_REMATCH[3]}
            regex='^(alt-|ea-|plesk-)?php'
            if [[ $P_NAME =~ $regex ]]; then
                P_TYPE=rpm P_FULL=$P_VERSION-$P_RELEASE
                return 0
            fi
            return 1
        fi
    done
    return 1
}

is_runtime() {
    [[ $P_TYPE == phpv ]] && return 0
    local excluded='pecl|pear|-ioncube|-imagick|-redis|-memcache|-apcu|-xdebug|-igbinary|-msgpack|-mcrypt|-oci8|-sodium'
    [[ $P_NAME =~ $excluded ]] && return 1
    local runtime='(^|-)php[0-9]*(-(fpm|cli|common|cgi|litespeed|embedded|dbg|devel))?$|^libapache2-mod-php|^php[0-9]+\.[0-9]+(-(fpm|cli|common|cgi|phpdbg))?$|^php[0-9]*-(fpm|cli|common|cgi|litespeed)$'
    [[ $P_NAME =~ $runtime ]]
}

family_key() {
    local regex='^((alt-|ea-|plesk-)?php[0-9]*(\.[0-9]+)?(-php)?)'
    KEY=$P_NAME
    [[ $P_NAME =~ $regex ]] && KEY=${BASH_REMATCH[1]}
    KEY=$KEY'|'$P_TYPE
}

fill_fix() {
    local template=$1 branch=$2 scl='' regex='^(php[0-9]+)-php'
    [[ $P_NAME =~ $regex ]] && scl=${BASH_REMATCH[1]}
    template=${template//\{scl\}/$scl}
    template=${template//\{nodot\}/${branch/./}}
    template=${template//\{branch\}/$branch}
    FIX=${template//\{pkg\}/$P_NAME}
}

rule_by_id() {
    local i
    RULE_INDEX=-1
    for ((i=0; i<RULE_COUNT; i++)); do
        if [[ ${R_ID[i]} == "$1" ]]; then RULE_INDEX=$i; return; fi
    done
}

gps_fix_for() {
    local branch=$1 regex='^php[0-9]+-php'
    if [[ $P_NAME =~ $regex ]]; then rule_by_id gps-el7-scl; else rule_by_id gps-el7-base; fi
    FIX=
    ((RULE_INDEX >= 0)) && fill_fix "${R_FIX[RULE_INDEX]}" "$branch"
    return 0
}

judge_with_rule() {
    local i=$1 subject target installed
    [[ ${R_TYPE[i]} == "$P_TYPE" && $P_NAME =~ ${R_NAME[i]} ]] || return 1
    subject=$P_RELEASE
    [[ $P_TYPE == deb ]] && subject=$P_FULL
    [[ -z ${R_RELEASE[i]} || $subject =~ ${R_RELEASE[i]} ]] || return 1
    [[ -z ${R_UPSTREAM[i]} || $P_VERSION =~ ${R_UPSTREAM[i]} ]] || return 1
    upstream_of "$P_VERSION"
    VENDOR=${R_VENDOR[i]} NOTE=${R_NOTE[i]} FIX='' FIXED_IN='' HAS_FIXED=0 HAS_FIX=0 HAS_BRANCH=0
    if [[ ${R_VERDICT[i]} == vulnerable ]]; then
        if [[ ${GPS_BRANCH["$i|$U_BRANCH"]} == gps-el7 ]]; then gps_fix_for "$U_BRANCH"
        else fill_fix "${R_FIX[i]}" "$U_BRANCH"; fi
        VERDICT=vulnerable HAS_FIX=1
        return 0
    fi
    if [[ ${R_VERDICT[i]} == patched ]]; then VERDICT=patched; return 0; fi
    # A vendor's explicit backport entry for this branch beats the generic
    # upstream mode (mirrors judgeWithRule in vendor/php2shell.js: Surý
    # rebases 8.2+ but backports the fix into EOL branches it still builds).
    target=
    if [[ -n $U_FULL ]]; then
        target=${RULE_FIXED["$i|$U_FULL"]}
        [[ -z $target ]] && target=${RULE_FIXED["$i|$U_BRANCH"]}
    fi
    if [[ -n $target ]]; then
        installed=$P_VERSION-$P_RELEASE
        [[ $P_TYPE == deb ]] && installed=$P_FULL
        vercmp "$installed" "$target"
        FIXED_IN=$target HAS_FIXED=1 VERDICT=patched
        if ((CMP < 0)); then
            VERDICT=vulnerable HAS_FIX=1
            fill_fix "${R_FIX[i]}" "$U_BRANCH"
        fi
        return 0
    fi
    if [[ ${R_MODE[i]} == upstream ]]; then
        upstream_status "$P_VERSION"
        if [[ $STATUS == fixed ]]; then
            VERDICT=patched FIXED_IN=$UP_FIXED HAS_FIXED=1
        elif [[ $STATUS == vulnerable ]]; then
            VERDICT=vulnerable FIXED_IN=$UP_FIXED HAS_FIXED=1 HAS_FIX=1
            NOTE="PHP $P_VERSION predates the fix."
            fill_fix "${R_FIX[i]}" "$U_BRANCH"
        else
            VERDICT=unknown NOTE=${R_EOL_NOTE[i]} HAS_FIX=1
            fill_fix "${R_FIX[i]}" "$U_BRANCH"
        fi
        return 0
    fi
    return 1
}

generic_fix() {
    case $P_TYPE in
        deb) FIX="sudo apt update && sudo apt install --only-upgrade \$(dpkg -l 'php*' | awk '/^ii/{print \$2}')" ;;
        apk) FIX='apk update && apk upgrade' ;;
        rpm)
            if [[ $P_NAME == ea-php* ]]; then
                FIX="yum update 'ea-php*' && /scripts/restartsrv_apache_php_fpm"
            elif [[ $P_NAME == alt-php* ]]; then
                FIX="yum update 'alt-php*'"
            elif [[ $P_NAME == plesk-php* ]]; then
                FIX='plesk installer --select-release-current --upgrade-installed-components'
            elif [[ $P_RELEASE == *.el7* ]]; then
                FIX='yum-config-manager --enable getpagespeed-extras-php84 && yum install php84-getpagespeed-stack'
            else FIX="sudo dnf upgrade 'php*'"; fi ;;
        *) FIX='' ;;
    esac
}

judge() {
    local i
    for ((i=0; i<RULE_COUNT; i++)); do
        judge_with_rule "$i" && return 0
    done
    upstream_status "$P_VERSION"
    VENDOR='' NOTE='' FIX='' FIXED_IN='' HAS_FIXED=0 HAS_FIX=0 HAS_BRANCH=0 BRANCH=$U_BRANCH
    [[ -n $U_BRANCH ]] && HAS_BRANCH=1
    if [[ $STATUS == fixed ]]; then
        VERDICT=patched NOTE="PHP $P_VERSION carries the upstream fix (first fixed: $UP_FIXED)."
    elif [[ $STATUS == unknown ]]; then
        VERDICT=unknown NOTE='Could not read a PHP version from this line.'
        if ((ANCIENT)); then
            NOTE="PHP $P_VERSION is older than every branch the advisories assessed and has had no security fixes for years. Treat it as compromised-ready and replace it."
        fi
    elif [[ $P_TYPE == phpv ]]; then
        VERDICT=unknown
        if [[ $STATUS == eol ]]; then
            NOTE="PHP $U_BRANCH got no upstream fix, so this build is vulnerable unless your vendor backported it, and php -v cannot show that. Paste your package list (rpm -qa or dpkg -l) for a definite answer."
        else
            NOTE="Upstream PHP $P_VERSION is vulnerable (fixed in $UP_FIXED), but distributions backport the fix without changing this number. Paste your package list (rpm -qa or dpkg -l) for a definite answer."
        fi
    else
        VERDICT=unknown HAS_FIX=1
        if [[ $STATUS == eol ]]; then NOTE="PHP $U_BRANCH got no upstream release with the fix."
        else NOTE="Upstream $P_VERSION predates the fix ($UP_FIXED)."; fi
        NOTE+=" This package comes from a vendor we have no rule for yet, so only its changelog can say whether the fix was backported: rpm -q --changelog $P_NAME | grep -E \"2026-10961[89]\" (or apt changelog $P_NAME)."
        generic_fix
    fi
    return 0
}

package_json() {
    json_quote "$P_TYPE"; PKG_JSON="{\"type\":$JSON"
    json_quote "$P_NAME"; PKG_JSON+=",\"name\":$JSON"
    json_quote "$P_VERSION"; PKG_JSON+=",\"version\":$JSON"
    if [[ $P_TYPE != phpv ]]; then
        json_quote "$P_FULL"; PKG_JSON+=",\"full\":$JSON"
    fi
    if [[ $P_TYPE == rpm || $P_TYPE == apk ]]; then
        json_quote "$P_RELEASE"; PKG_JSON+=",\"release\":$JSON"
    fi
    json_quote "$P_RAW"; PKG_JSON+=",\"raw\":$JSON}"
}

result_json() {
    package_json
    json_quote "$VERDICT"; RESULT="{\"verdict\":$JSON,\"pkg\":$PKG_JSON"
    json_quote "$VENDOR"; RESULT+=",\"vendor\":$JSON"
    json_quote "$NOTE"; RESULT+=",\"note\":$JSON"
    if ((HAS_BRANCH)); then json_quote "$BRANCH"; RESULT+=",\"branch\":$JSON"; fi
    if ((HAS_FIXED)); then json_quote "$FIXED_IN"; RESULT+=",\"fixedIn\":$JSON"; fi
    if ((HAS_FIX)); then json_quote "$FIX"; RESULT+=",\"fix\":$JSON"; fi
    RESULT+='}'
}

usage() {
    cat <<'HELP'
Usage: php2shell-check.sh [--json] [--file PATH|-]
Check installed PHP packages for PHP2Shell vendor fixes.
  --file PATH   Read rpm -qa, dpkg -l, apk info -v or php -v output
  --json        Emit the web checker's JSON report
  --help        Show this help
  --version     Show the rules update date
Exit: 0 all fixed; 1 vulnerable; 3 unknown or no PHP; 2 usage error.
https://www.getpagespeed.com/php2shell
HELP
}

main() {
    local json_mode=0 file='' text line gps_built=0 rank key overall=none overall_rank=0 separator='' item tag
    local -A ranks=() reports=() human=()
    local -a order=()
    while (($#)); do
        case $1 in
            --json) json_mode=1; shift ;;
            --file)
                if (($# < 2)) || [[ -z $2 ]]; then usage >&2; return 2; fi
                file=$2; shift 2 ;;
            --help) usage; return 0 ;;
            --version) printf '%s\n' "$UPDATED"; return 0 ;;
            *) usage >&2; return 2 ;;
        esac
    done
    if [[ -n $file ]]; then
        if [[ $file == - ]]; then text=$(cat) || return 2
        elif [[ -r $file && ! -d $file ]]; then text=$(cat -- "$file") || return 2
        else printf 'Cannot read file: %s\n' "$file" >&2; return 2; fi
    elif command -v rpm >/dev/null 2>&1; then
        text=$(rpm -qa --qf '%{NAME}-%{VERSION}-%{RELEASE}.%{ARCH}\n') || return 2
    elif command -v dpkg-query >/dev/null 2>&1; then
        # dpkg -l format also handles plain Debian versions without + or ~.
        text=$(dpkg-query -W -f='ii  ${Package} ${Version} ${Architecture}\n') || return 2
    elif command -v apk >/dev/null 2>&1; then
        text=$(apk info -v) || return 2
    else printf '%s\n' 'No supported package manager found.' >&2; return 2; fi
    local lower=${text,,}
    [[ $lower == *'built by getpagespeed llc'* ]] && gps_built=1
    while IFS='' read -r line || [[ -n $line ]]; do
        parse_line "$line" || continue
        is_runtime || continue
        family_key; key=$KEY
        if [[ -z ${ranks[$key]} ]]; then order+=("$key"); fi
        judge
        case $VERDICT in vulnerable) rank=3 ;; unknown) rank=2 ;; patched) rank=1 ;; esac
        if ((rank <= ${ranks[$key]:-0})); then continue; fi
        if [[ $P_TYPE == phpv ]] && ((gps_built)); then
            NOTE+=" This binary was built by GetPageSpeed: run rpm -qa 'php*-common' to see its release."
        fi
        result_json
        ranks[$key]=$rank reports[$key]=$RESULT
        case $VERDICT in patched) tag=FIXED ;; vulnerable) tag=VULNERABLE ;; *) tag=UNKNOWN ;; esac
        item="[$tag] ${VENDOR:-Unrecognized package}: $P_NAME ${P_FULL:-$P_VERSION}"
        if [[ $VERDICT == vulnerable && -n $FIX ]]; then item+=$'\n'$FIX; fi
        human[$key]=$item
    done <<< "$text"
    for key in "${order[@]}"; do
        if ((${ranks[$key]} > overall_rank)); then overall_rank=${ranks[$key]}; fi
    done
    case $overall_rank in 1) overall=patched ;; 2) overall=unknown ;; 3) overall=vulnerable ;; esac
    if ((json_mode)); then
        printf '{"overall":"%s","results":[' "$overall"
        for key in "${order[@]}"; do printf '%s%s' "$separator" "${reports[$key]}"; separator=,; done
        printf ']}\n'
    else
        if ((${#order[@]} == 0)); then printf '%s\n' 'No PHP found.'; fi
        for key in "${order[@]}"; do printf '%s\n' "${human[$key]}"; done
        printf '%s\n' 'https://www.getpagespeed.com/php2shell'
    fi
    case $overall in patched) return 0 ;; vulnerable) return 1 ;; *) return 3 ;; esac
}
main "$@"
